-- GENERATED by tools/build_schema.sh from backend/migrations/sql/*.sql. Do not edit by hand.

-- ===== 00_platform.sql =====
-- 00_platform: extensions, roles, tenancy helpers, outbox, idempotency, audit.
-- Files in this directory are applied in filename order = dependency order.

CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE EXTENSION IF NOT EXISTS citext;
CREATE EXTENSION IF NOT EXISTS pg_trgm;
CREATE EXTENSION IF NOT EXISTS vector;   -- pgvector >= 0.8

-- Roles are NOLOGIN here; infra grants LOGIN + password per environment.
DO $$
DECLARE r text;
BEGIN
  FOREACH r IN ARRAY ARRAY['viewora_app', 'viewora_relay', 'viewora_discovery_writer', 'viewora_readonly'] LOOP
    IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = r) THEN
      EXECUTE format('CREATE ROLE %I NOLOGIN NOBYPASSRLS', r);
    END IF;
  END LOOP;
END $$;

CREATE SCHEMA IF NOT EXISTS platform;

-- Tenant context. Set per transaction: set_config('app.tenant_id', '<uuid>', true).
CREATE FUNCTION platform.app_tenant_id() RETURNS uuid
LANGUAGE sql STABLE AS
$$ SELECT nullif(current_setting('app.tenant_id', true), '')::uuid $$;

CREATE FUNCTION platform.app_user_id() RETURNS uuid
LANGUAGE sql STABLE AS
$$ SELECT nullif(current_setting('app.user_id', true), '')::uuid $$;

-- UUIDv7 (time-ordered). The application generates ids; this exists for seeds, tests and defaults.
CREATE FUNCTION platform.uuid_v7() RETURNS uuid
LANGUAGE sql VOLATILE AS
$$
  SELECT encode(
    set_bit(
      set_bit(
        overlay(uuid_send(gen_random_uuid())
                PLACING substring(int8send(floor(extract(epoch FROM clock_timestamp()) * 1000)::bigint) FROM 3)
                FROM 1 FOR 6),
        52, 1),
      53, 1),
    'hex')::uuid
$$;

CREATE FUNCTION platform.set_updated_at() RETURNS trigger
LANGUAGE plpgsql AS
$$ BEGIN NEW.updated_at := now(); RETURN NEW; END $$;

-- Enables FORCE RLS with the standard tenant policy on a table.
-- `col` is the column holding the tenant id (default tenant_id; merchants uses id).
CREATE FUNCTION platform.enable_tenant_rls(tbl regclass, col name DEFAULT 'tenant_id') RETURNS void
LANGUAGE plpgsql AS
$$
BEGIN
  EXECUTE format('ALTER TABLE %s ENABLE ROW LEVEL SECURITY', tbl);
  EXECUTE format('ALTER TABLE %s FORCE ROW LEVEL SECURITY', tbl);
  EXECUTE format('DROP POLICY IF EXISTS tenant_isolation ON %s', tbl);
  EXECUTE format(
    'CREATE POLICY tenant_isolation ON %s USING (%I = platform.app_tenant_id()) WITH CHECK (%I = platform.app_tenant_id())',
    tbl, col, col);
END
$$;

-- Transactional outbox (ADR-0009). Written in the same transaction as the state change.
-- No RLS: the relay reads across tenants. tenant_id is informational and travels with the event.
CREATE TABLE platform.outbox (
  id             uuid PRIMARY KEY DEFAULT platform.uuid_v7(),
  tenant_id      uuid,
  topic          text        NOT NULL,                 -- e.g. catalog.product.changed
  aggregate_type text        NOT NULL,
  aggregate_id   uuid        NOT NULL,
  payload        jsonb       NOT NULL,
  created_at     timestamptz NOT NULL DEFAULT now(),
  published_at   timestamptz,
  attempts       integer     NOT NULL DEFAULT 0
);
CREATE INDEX outbox_unpublished ON platform.outbox (id) WHERE published_at IS NULL;

-- Idempotency backstop (primary store is State Redis). scope = tenant id text, or 'global'.
CREATE TABLE platform.idempotency_keys (
  scope        text        NOT NULL,
  key          text        NOT NULL,
  request_hash bytea       NOT NULL,
  status_code  integer,
  response     jsonb,
  created_at   timestamptz NOT NULL DEFAULT now(),
  expires_at   timestamptz NOT NULL DEFAULT now() + interval '24 hours',
  PRIMARY KEY (scope, key)
);
CREATE INDEX idempotency_expires ON platform.idempotency_keys (expires_at);

-- Append-only audit trail (ADM-02). UPDATE/DELETE are revoked in 99_grants.sql.
CREATE TABLE platform.audit_log (
  id            uuid PRIMARY KEY DEFAULT platform.uuid_v7(),
  tenant_id     uuid,
  actor_user_id uuid,
  actor_kind    text        NOT NULL CHECK (actor_kind IN ('merchant_user', 'platform_admin', 'system')),
  action        text        NOT NULL,                  -- e.g. product.update
  entity_type   text        NOT NULL,
  entity_id     uuid,
  before        jsonb,
  after         jsonb,
  request_id    text,
  created_at    timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX audit_log_tenant_time ON platform.audit_log (tenant_id, created_at DESC);
CREATE INDEX audit_log_entity ON platform.audit_log (entity_type, entity_id, created_at DESC);
SELECT platform.enable_tenant_rls('platform.audit_log');

-- ===== 01_ref.sql =====
-- 01_ref: shared reference data (no tenant, no RLS). Read-only for the application.

CREATE SCHEMA IF NOT EXISTS ref;

-- Per-vertical profile (glossary: "Vertical profile").
CREATE TABLE ref.vertical_profiles (
  code             text PRIMARY KEY CHECK (code ~ '^[a-z_]+$'),
  name             text    NOT NULL,
  attribute_schema jsonb   NOT NULL,                   -- JSON Schema for products.attributes
  viewer_config    jsonb   NOT NULL DEFAULT '{}',
  tryon_kind       text    CHECK (tryon_kind IN ('glasses', 'clothing', 'earrings', 'necklace')),
  required_assets  text[]  NOT NULL DEFAULT '{}',
  active           boolean NOT NULL DEFAULT true
);

-- Canonical taxonomy = Google product taxonomy. id is Google's numeric id.
CREATE TABLE ref.categories (
  id        integer PRIMARY KEY,
  parent_id integer REFERENCES ref.categories (id),
  name      text    NOT NULL,
  path      text    NOT NULL,                          -- 'Apparel & Accessories > Clothing > Dresses'
  depth     smallint NOT NULL CHECK (depth >= 1),
  family    text    NOT NULL                           -- retrieval partition (discovery); see ADR-0016
);
CREATE INDEX categories_parent ON ref.categories (parent_id);
CREATE INDEX categories_family ON ref.categories (family);

