-- ===== 02_identity.sql =====
-- 02_identity: users (global), merchants (= tenants), memberships, sessions, shopper addresses.

CREATE SCHEMA IF NOT EXISTS identity;

-- Users are global (merchant staff and shoppers). Access to a merchant is through memberships.
-- Short-lived secrets (password reset, 2FA OTP) live in State Redis with a TTL, not here (ADR-0007).
CREATE TABLE identity.users (
  id                    uuid PRIMARY KEY DEFAULT platform.uuid_v7(),
  email                 citext UNIQUE,
  phone                 text   UNIQUE,
  password_hash         text,                                   -- Argon2id; null for OTP-only shoppers
  name                  text,
  locale                text        NOT NULL DEFAULT 'en',
  failed_login_attempts integer     NOT NULL DEFAULT 0 CHECK (failed_login_attempts >= 0),
  locked_until          timestamptz,
  two_factor_enabled    boolean     NOT NULL DEFAULT false,
  status                text        NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'suspended', 'deleted')),
  avatar_key            text,
  preferences           jsonb       NOT NULL DEFAULT '{}',
  created_at            timestamptz NOT NULL DEFAULT now(),
  updated_at            timestamptz NOT NULL DEFAULT now(),
  deleted_at            timestamptz,
  CHECK (email IS NOT NULL OR phone IS NOT NULL),
  CHECK (phone IS NULL OR phone ~ '^\+[1-9][0-9]{7,14}$')
);
CREATE TRIGGER users_updated BEFORE UPDATE ON identity.users
  FOR EACH ROW EXECUTE FUNCTION platform.set_updated_at();

-- Merchant = tenant. merchants.id is the tenant id.
CREATE TABLE identity.merchants (
  id                 uuid PRIMARY KEY DEFAULT platform.uuid_v7(),
  slug               citext      NOT NULL UNIQUE,
  name               text        NOT NULL,
  primary_vertical   text        NOT NULL REFERENCES ref.vertical_profiles (code),
  status             text        NOT NULL DEFAULT 'pending'
                       CHECK (status IN ('pending', 'active', 'suspended', 'closed')),
  discovery_opt_in   boolean     NOT NULL DEFAULT false,       -- DSC-06
  branding           jsonb       NOT NULL DEFAULT '{}',        -- logo asset, colours, font from a fixed set
  contact            jsonb       NOT NULL DEFAULT '{}',
  created_at         timestamptz NOT NULL DEFAULT now(),
  updated_at         timestamptz NOT NULL DEFAULT now(),
  deleted_at         timestamptz,
  CHECK (slug::text ~ '^[a-z0-9][a-z0-9-]{1,38}[a-z0-9]$'),
  CHECK (slug::text NOT IN ('q','api','app','admin','static','assets','help','login','signup',
                            'search','cart','checkout','orders','legal','about'))
);
CREATE TRIGGER merchants_updated BEFORE UPDATE ON identity.merchants
  FOR EACH ROW EXECUTE FUNCTION platform.set_updated_at();

-- Every slug a merchant has held, current or old. Old slugs redirect; no one else can claim them.
CREATE TABLE identity.merchant_slugs (
  slug        citext      PRIMARY KEY,
  merchant_id uuid        NOT NULL REFERENCES identity.merchants (id) ON DELETE CASCADE,
  is_current  boolean     NOT NULL DEFAULT true,
  created_at  timestamptz NOT NULL DEFAULT now()
);
CREATE UNIQUE INDEX merchant_slugs_one_current ON identity.merchant_slugs (merchant_id) WHERE is_current;

CREATE FUNCTION identity.sync_merchant_slug() RETURNS trigger
LANGUAGE plpgsql AS
$$
BEGIN
  UPDATE identity.merchant_slugs SET is_current = false
   WHERE merchant_id = NEW.id AND is_current AND slug <> NEW.slug;
  INSERT INTO identity.merchant_slugs (slug, merchant_id, is_current)
  VALUES (NEW.slug, NEW.id, true)
  ON CONFLICT (slug) DO UPDATE SET is_current = true
    WHERE identity.merchant_slugs.merchant_id = NEW.id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'merchant slug % is held by another merchant', NEW.slug USING ERRCODE = 'unique_violation';
  END IF;
  RETURN NEW;
END
$$;
CREATE TRIGGER merchants_slug_ins AFTER INSERT ON identity.merchants
  FOR EACH ROW EXECUTE FUNCTION identity.sync_merchant_slug();
CREATE TRIGGER merchants_slug_upd AFTER UPDATE OF slug ON identity.merchants
  FOR EACH ROW WHEN (OLD.slug IS DISTINCT FROM NEW.slug) EXECUTE FUNCTION identity.sync_merchant_slug();

-- A user's role inside a merchant. One login can belong to many merchants.
CREATE TABLE identity.memberships (
  tenant_id  uuid        NOT NULL REFERENCES identity.merchants (id) ON DELETE CASCADE,
  user_id    uuid        NOT NULL REFERENCES identity.users (id) ON DELETE CASCADE,
  role       text        NOT NULL CHECK (role IN ('owner', 'manager', 'staff')),
  created_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (tenant_id, user_id)
);
CREATE INDEX memberships_user ON identity.memberships (user_id);

-- Rotating refresh tokens with reuse detection (a reused rotated token revokes the whole family).
CREATE TABLE identity.refresh_tokens (
  id          uuid PRIMARY KEY DEFAULT platform.uuid_v7(),
  user_id     uuid        NOT NULL REFERENCES identity.users (id) ON DELETE CASCADE,
  family_id   uuid        NOT NULL,
  token_hash  bytea       NOT NULL UNIQUE,
  issued_at   timestamptz NOT NULL DEFAULT now(),
  expires_at  timestamptz NOT NULL,
  rotated_at  timestamptz,
  revoked_at  timestamptz,
  device_info text,
  ip_hash     bytea
);
CREATE INDEX refresh_tokens_user ON identity.refresh_tokens (user_id);
CREATE INDEX refresh_tokens_family ON identity.refresh_tokens (family_id);
CREATE INDEX refresh_tokens_expiry ON identity.refresh_tokens (expires_at);

CREATE TABLE identity.shopper_addresses (
  id         uuid PRIMARY KEY DEFAULT platform.uuid_v7(),
  user_id    uuid        NOT NULL REFERENCES identity.users (id) ON DELETE CASCADE,
  label      text,
  name       text        NOT NULL,
  phone      text        NOT NULL,
  line1      text        NOT NULL,
  line2      text,
  city       text        NOT NULL,
  state      text        NOT NULL,
  pincode    text        NOT NULL CHECK (pincode ~ '^[1-9][0-9]{5}$'),
  is_default boolean     NOT NULL DEFAULT false,
  created_at timestamptz NOT NULL DEFAULT now(),
  deleted_at timestamptz
);
CREATE UNIQUE INDEX shopper_addresses_one_default ON identity.shopper_addresses (user_id)
  WHERE is_default AND deleted_at IS NULL;

-- Platform staff (admin console). Merchant data is reached by setting a tenant context, never by bypassing RLS.
CREATE TABLE identity.platform_roles (
  user_id    uuid PRIMARY KEY REFERENCES identity.users (id) ON DELETE CASCADE,
  role       text        NOT NULL CHECK (role IN ('super_admin', 'ops_admin', 'support')),
  created_at timestamptz NOT NULL DEFAULT now()
);

-- RLS --------------------------------------------------------------------------------------------
-- merchants: a tenant sees itself. Slug lookup before the tenant is known (storefront resolve) is allowed
-- only when the caller sets app.merchant_slug to the exact slug (public data).
SELECT platform.enable_tenant_rls('identity.merchants', 'id');
CREATE POLICY lookup_by_slug ON identity.merchants FOR SELECT
  USING (slug::text = nullif(current_setting('app.merchant_slug', true), ''));

-- memberships: visible within the tenant, or to the user themself (login lists their merchants).
ALTER TABLE identity.memberships ENABLE ROW LEVEL SECURITY;
ALTER TABLE identity.memberships FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_or_self ON identity.memberships
  USING (tenant_id = platform.app_tenant_id() OR user_id = platform.app_user_id())
  WITH CHECK (tenant_id = platform.app_tenant_id());

ALTER TABLE identity.shopper_addresses ENABLE ROW LEVEL SECURITY;
ALTER TABLE identity.shopper_addresses FORCE ROW LEVEL SECURITY;
CREATE POLICY own_rows ON identity.shopper_addresses
  USING (user_id = platform.app_user_id()) WITH CHECK (user_id = platform.app_user_id());

-- ===== 03_billing.sql =====
-- 03_billing: plans, subscriptions, credit ledger. Entitlements are resolved in code from plan.limits (BIL-03).

CREATE SCHEMA IF NOT EXISTS billing;

CREATE TABLE billing.plans (
  code             text PRIMARY KEY CHECK (code ~ '^[a-z0-9_]+$'),
  name             text    NOT NULL,
  price_paise      bigint  NOT NULL CHECK (price_paise >= 0),
  billing_interval text    NOT NULL CHECK (billing_interval IN ('month', 'year')),
  limits           jsonb   NOT NULL,        -- products, assets, ai_credits, tryon_calls, qr_codes ...
  razorpay_plan_id text    UNIQUE,
  active           boolean NOT NULL DEFAULT true
);

CREATE TABLE billing.subscriptions (
  id                       uuid PRIMARY KEY DEFAULT platform.uuid_v7(),
  tenant_id                uuid        NOT NULL REFERENCES identity.merchants (id),
  plan_code                text        NOT NULL REFERENCES billing.plans (code),
  status                   text        NOT NULL
                             CHECK (status IN ('trialing', 'active', 'past_due', 'cancelled', 'expired')),
  razorpay_subscription_id text UNIQUE,
  trial_ends_at            timestamptz,
  current_period_start     timestamptz,
  current_period_end       timestamptz,
  cancel_at_period_end     boolean     NOT NULL DEFAULT false,
  grace_until              timestamptz,
  created_at               timestamptz NOT NULL DEFAULT now(),
  updated_at               timestamptz NOT NULL DEFAULT now()
);
-- At most one live subscription per merchant.
CREATE UNIQUE INDEX subscriptions_one_live ON billing.subscriptions (tenant_id)
  WHERE status IN ('trialing', 'active', 'past_due');
CREATE TRIGGER subscriptions_updated BEFORE UPDATE ON billing.subscriptions
  FOR EACH ROW EXECUTE FUNCTION platform.set_updated_at();
SELECT platform.enable_tenant_rls('billing.subscriptions');

-- Append-only ledger (BIL-05). The (ref_type, ref_id) pair makes a charge or refund idempotent.
CREATE TABLE billing.credit_ledger (
  id         uuid PRIMARY KEY DEFAULT platform.uuid_v7(),
  tenant_id  uuid        NOT NULL REFERENCES identity.merchants (id),
  kind       text        NOT NULL CHECK (kind IN ('ai_generation', 'tryon')),
  delta      integer     NOT NULL CHECK (delta <> 0),
  reason     text        NOT NULL CHECK (reason IN ('plan_grant', 'purchase', 'usage', 'refund', 'adjustment')),
  ref_type   text,
  ref_id     uuid,
  created_at timestamptz NOT NULL DEFAULT now()
);
CREATE UNIQUE INDEX credit_ledger_idempotent ON billing.credit_ledger (tenant_id, kind, reason, ref_type, ref_id)
  WHERE ref_id IS NOT NULL;
CREATE INDEX credit_ledger_tenant ON billing.credit_ledger (tenant_id, created_at DESC);
SELECT platform.enable_tenant_rls('billing.credit_ledger');

-- Balance is kept by trigger in the same transaction, so overspend is impossible (CHECK fails the insert).
CREATE TABLE billing.credit_balances (
  tenant_id  uuid        NOT NULL REFERENCES identity.merchants (id),
  kind       text        NOT NULL CHECK (kind IN ('ai_generation', 'tryon')),
  balance    integer     NOT NULL CHECK (balance >= 0),
  updated_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (tenant_id, kind)
);
SELECT platform.enable_tenant_rls('billing.credit_balances');

CREATE FUNCTION billing.apply_ledger_entry() RETURNS trigger
LANGUAGE plpgsql AS
$$
BEGIN
  IF NEW.delta > 0 THEN
    INSERT INTO billing.credit_balances AS b (tenant_id, kind, balance)
    VALUES (NEW.tenant_id, NEW.kind, NEW.delta)
    ON CONFLICT (tenant_id, kind) DO UPDATE
      SET balance = b.balance + EXCLUDED.balance, updated_at = now();
  ELSE
    -- Debits never use the upsert: the proposed row would fail the CHECK before ON CONFLICT is considered.
    UPDATE billing.credit_balances SET balance = balance + NEW.delta, updated_at = now()
     WHERE tenant_id = NEW.tenant_id AND kind = NEW.kind;       -- CHECK (balance >= 0) rejects overspend
    IF NOT FOUND THEN
      RAISE EXCEPTION 'insufficient % credits', NEW.kind USING ERRCODE = 'check_violation';
    END IF;
  END IF;
  RETURN NEW;
END
$$;
CREATE TRIGGER credit_ledger_apply AFTER INSERT ON billing.credit_ledger
  FOR EACH ROW EXECUTE FUNCTION billing.apply_ledger_entry();

-- ===== 04_assets.sql =====
-- 04_assets: originals and derived files. Bytes live in object storage; this is metadata only (AST-01, AST-09).

CREATE SCHEMA IF NOT EXISTS assets;

CREATE TABLE assets.assets (
  id              uuid PRIMARY KEY DEFAULT platform.uuid_v7(),
  tenant_id       uuid        NOT NULL REFERENCES identity.merchants (id),
  kind            text        NOT NULL CHECK (kind IN ('model', 'image', 'usdz', 'document')),
  source          text        NOT NULL CHECK (source IN ('merchant_upload', 'ai_generation', 'assisted')),
  status          text        NOT NULL DEFAULT 'pending_upload'
                    CHECK (status IN ('pending_upload', 'uploaded', 'processing', 'ready', 'rejected')),
  original_key    text        NOT NULL,                -- object-store key of the untouched original
  original_sha256 bytea,
  bytes           bigint      CHECK (bytes >= 0),
  content_type    text,
  rejections      jsonb       NOT NULL DEFAULT '[]',   -- actionable reasons from the pipeline (AST-06)
  metadata        jsonb       NOT NULL DEFAULT '{}',   -- extracted: bbox, triangle count, texture sizes
  created_by      uuid        REFERENCES identity.users (id),
  created_at      timestamptz NOT NULL DEFAULT now(),
  updated_at      timestamptz NOT NULL DEFAULT now(),
  deleted_at      timestamptz,
  UNIQUE (tenant_id, id)
);
CREATE INDEX assets_tenant_status ON assets.assets (tenant_id, status) WHERE deleted_at IS NULL;
CREATE INDEX assets_processing ON assets.assets (updated_at) WHERE status IN ('uploaded', 'processing');
CREATE TRIGGER assets_updated BEFORE UPDATE ON assets.assets
  FOR EACH ROW EXECUTE FUNCTION platform.set_updated_at();
SELECT platform.enable_tenant_rls('assets.assets');

-- Pipeline outputs, served from immutable content-hash URLs (AST-04). Reproducible from the original.
CREATE TABLE assets.derivatives (
  id               uuid PRIMARY KEY DEFAULT platform.uuid_v7(),
  tenant_id        uuid        NOT NULL,
  asset_id         uuid        NOT NULL,
  variant          text        NOT NULL
                     CHECK (variant IN ('lod0', 'lod1', 'poster', 'thumb', 'usdz', 'avif', 'webp')),
  width            integer     CHECK (width > 0),       -- image srcset widths
  storage_key      text        NOT NULL,                -- includes the content hash
  content_hash     bytea       NOT NULL,
  bytes            bigint      NOT NULL CHECK (bytes > 0),
  height           integer     CHECK (height > 0),
  triangles        integer     CHECK (triangles >= 0),
  texture_max_px   integer     CHECK (texture_max_px > 0),
  pipeline_version text        NOT NULL,
  created_at       timestamptz NOT NULL DEFAULT now(),
  FOREIGN KEY (tenant_id, asset_id) REFERENCES assets.assets (tenant_id, id) ON DELETE CASCADE
);
CREATE UNIQUE INDEX derivatives_unique ON assets.derivatives (asset_id, variant, coalesce(width, 0));
SELECT platform.enable_tenant_rls('assets.derivatives');

-- ===== 05_catalog.sql =====
-- 05_catalog: products, variants, slugs, collections, media links, try-on metadata, saved products.
-- Cross-table references inside a tenant use composite (tenant_id, id) foreign keys, so a row can
-- never point at another tenant's row even if application code is wrong.

CREATE SCHEMA IF NOT EXISTS catalog;

CREATE TABLE catalog.collections (
  id          uuid PRIMARY KEY DEFAULT platform.uuid_v7(),
  tenant_id   uuid        NOT NULL REFERENCES identity.merchants (id),
  name        text        NOT NULL,
  slug        citext      NOT NULL CHECK (slug::text ~ '^[a-z0-9]+(-[a-z0-9]+)*$'),
  description text,
  status      text        NOT NULL DEFAULT 'published' CHECK (status IN ('draft', 'published', 'archived')),
  position    integer     NOT NULL DEFAULT 0,
  created_at  timestamptz NOT NULL DEFAULT now(),
  updated_at  timestamptz NOT NULL DEFAULT now(),
  deleted_at  timestamptz,
  UNIQUE (tenant_id, id)
);
CREATE UNIQUE INDEX collections_slug ON catalog.collections (tenant_id, slug) WHERE deleted_at IS NULL;
CREATE TRIGGER collections_updated BEFORE UPDATE ON catalog.collections
  FOR EACH ROW EXECUTE FUNCTION platform.set_updated_at();
SELECT platform.enable_tenant_rls('catalog.collections');

CREATE TABLE catalog.products (
  id            uuid PRIMARY KEY DEFAULT platform.uuid_v7(),
  tenant_id     uuid        NOT NULL REFERENCES identity.merchants (id),
  product_seq   bigint      GENERATED ALWAYS AS IDENTITY UNIQUE,    -- dense id for the in-stock bitmap; never exposed
  slug          citext      NOT NULL CHECK (slug::text ~ '^[a-z0-9]+(-[a-z0-9]+)*$' AND length(slug) <= 80),
  title         text        NOT NULL CHECK (length(title) BETWEEN 1 AND 200),
  tagline       text,
  description   text,
  brand         text,
  vertical      text        NOT NULL REFERENCES ref.vertical_profiles (code),
  category_id   integer     REFERENCES ref.categories (id),
  attributes    jsonb       NOT NULL DEFAULT '{}' CHECK (jsonb_typeof(attributes) = 'object'),  -- validated against the vertical profile in the service layer
  width_mm      integer     CHECK (width_mm > 0),                   -- declared real-world size, used by the pipeline scale check
  height_mm     integer     CHECK (height_mm > 0),
  depth_mm      integer     CHECK (depth_mm > 0),
  status        text        NOT NULL DEFAULT 'draft' CHECK (status IN ('draft', 'published', 'archived')),
  published_at  timestamptz,
  version       integer     NOT NULL DEFAULT 1,                     -- ETag / If-Match
  search        tsvector GENERATED ALWAYS AS (
                  setweight(to_tsvector('simple', coalesce(title, '')), 'A') ||
                  setweight(to_tsvector('simple', coalesce(brand, '')), 'B') ||
                  setweight(to_tsvector('simple', coalesce(tagline, '')), 'C') ||
                  setweight(to_tsvector('simple', coalesce(description, '')), 'D')
                ) STORED,
  created_by    uuid        REFERENCES identity.users (id),
  created_at    timestamptz NOT NULL DEFAULT now(),
  updated_at    timestamptz NOT NULL DEFAULT now(),
  deleted_at    timestamptz,
  UNIQUE (tenant_id, id),
  CHECK (status <> 'published' OR published_at IS NOT NULL)
);
CREATE INDEX products_tenant_status ON catalog.products (tenant_id, status, updated_at DESC) WHERE deleted_at IS NULL;
CREATE INDEX products_category ON catalog.products (tenant_id, category_id) WHERE deleted_at IS NULL;
CREATE INDEX products_attributes ON catalog.products USING gin (attributes jsonb_path_ops);
CREATE INDEX products_search ON catalog.products USING gin (search);
CREATE INDEX products_title_trgm ON catalog.products USING gin (title gin_trgm_ops);
CREATE TRIGGER products_updated BEFORE UPDATE ON catalog.products
  FOR EACH ROW EXECUTE FUNCTION platform.set_updated_at();
SELECT platform.enable_tenant_rls('catalog.products');

-- Every slug a product has held (current + old). Old slugs redirect; nobody else can take them. (CAT-04)
CREATE TABLE catalog.product_slugs (
  tenant_id  uuid        NOT NULL,
  slug       citext      NOT NULL,
  product_id uuid        NOT NULL,
  is_current boolean     NOT NULL DEFAULT true,
  created_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (tenant_id, slug),
  FOREIGN KEY (tenant_id, product_id) REFERENCES catalog.products (tenant_id, id) ON DELETE CASCADE
);
CREATE UNIQUE INDEX product_slugs_one_current ON catalog.product_slugs (product_id) WHERE is_current;
SELECT platform.enable_tenant_rls('catalog.product_slugs');

CREATE FUNCTION catalog.sync_product_slug() RETURNS trigger
LANGUAGE plpgsql AS
$$
BEGIN
  UPDATE catalog.product_slugs SET is_current = false
   WHERE tenant_id = NEW.tenant_id AND product_id = NEW.id AND is_current AND slug <> NEW.slug;
  INSERT INTO catalog.product_slugs (tenant_id, slug, product_id, is_current)
  VALUES (NEW.tenant_id, NEW.slug, NEW.id, true)
  ON CONFLICT (tenant_id, slug) DO UPDATE SET is_current = true
    WHERE catalog.product_slugs.product_id = NEW.id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'product slug % is held by another product', NEW.slug USING ERRCODE = 'unique_violation';
  END IF;
  RETURN NEW;
END
$$;
CREATE TRIGGER products_slug_ins AFTER INSERT ON catalog.products
  FOR EACH ROW EXECUTE FUNCTION catalog.sync_product_slug();
CREATE TRIGGER products_slug_upd AFTER UPDATE OF slug ON catalog.products
  FOR EACH ROW WHEN (OLD.slug IS DISTINCT FROM NEW.slug) EXECUTE FUNCTION catalog.sync_product_slug();

CREATE TABLE catalog.product_collections (
  tenant_id     uuid    NOT NULL,
  product_id    uuid    NOT NULL,
  collection_id uuid    NOT NULL,
  position      integer NOT NULL DEFAULT 0,
  PRIMARY KEY (product_id, collection_id),
  FOREIGN KEY (tenant_id, product_id)    REFERENCES catalog.products (tenant_id, id) ON DELETE CASCADE,
  FOREIGN KEY (tenant_id, collection_id) REFERENCES catalog.collections (tenant_id, id) ON DELETE CASCADE
);
CREATE INDEX product_collections_collection ON catalog.product_collections (collection_id, position);
SELECT platform.enable_tenant_rls('catalog.product_collections');

CREATE TABLE catalog.variants (
  id               uuid PRIMARY KEY DEFAULT platform.uuid_v7(),
  tenant_id        uuid        NOT NULL,
  product_id       uuid        NOT NULL,
  sku              text,
  option_values    jsonb       NOT NULL DEFAULT '{}',          -- {"size":"M","color":"black"}
  price_paise      bigint      NOT NULL CHECK (price_paise >= 0),
  compare_at_paise bigint      CHECK (compare_at_paise IS NULL OR compare_at_paise >= price_paise),
  currency         char(3)     NOT NULL DEFAULT 'INR' CHECK (currency = 'INR'),
  weight_g         integer     CHECK (weight_g >= 0),
  is_default       boolean     NOT NULL DEFAULT false,
  position         integer     NOT NULL DEFAULT 0,
  status           text        NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'inactive')),
  created_at       timestamptz NOT NULL DEFAULT now(),
  updated_at       timestamptz NOT NULL DEFAULT now(),
  deleted_at       timestamptz,
  UNIQUE (tenant_id, id),
  FOREIGN KEY (tenant_id, product_id) REFERENCES catalog.products (tenant_id, id) ON DELETE CASCADE
);
CREATE UNIQUE INDEX variants_sku ON catalog.variants (tenant_id, sku) WHERE sku IS NOT NULL AND deleted_at IS NULL;
CREATE UNIQUE INDEX variants_one_default ON catalog.variants (product_id) WHERE is_default AND deleted_at IS NULL;
CREATE INDEX variants_product ON catalog.variants (product_id, position) WHERE deleted_at IS NULL;
CREATE TRIGGER variants_updated BEFORE UPDATE ON catalog.variants
  FOR EACH ROW EXECUTE FUNCTION platform.set_updated_at();
SELECT platform.enable_tenant_rls('catalog.variants');

-- Which asset plays which role on a product.
CREATE TABLE catalog.product_media (
  tenant_id  uuid    NOT NULL,
  product_id uuid    NOT NULL,
  asset_id   uuid    NOT NULL,
  role       text    NOT NULL CHECK (role IN ('model', 'gallery', 'thumbnail', 'size_chart')),
  position   integer NOT NULL DEFAULT 0,
  PRIMARY KEY (product_id, role, asset_id),
  FOREIGN KEY (tenant_id, product_id) REFERENCES catalog.products (tenant_id, id) ON DELETE CASCADE,
  FOREIGN KEY (tenant_id, asset_id)   REFERENCES assets.assets (tenant_id, id)
);
-- One primary 3D model and one thumbnail per product.
CREATE UNIQUE INDEX product_media_one_model ON catalog.product_media (product_id) WHERE role = 'model';
CREATE UNIQUE INDEX product_media_one_thumb ON catalog.product_media (product_id) WHERE role = 'thumbnail';
SELECT platform.enable_tenant_rls('catalog.product_media');

-- Per-product try-on parameters, validated before try-on is enabled (TRY-05).
CREATE TABLE catalog.product_tryon (
  product_id   uuid PRIMARY KEY,
  tenant_id    uuid        NOT NULL,
  kind         text        NOT NULL CHECK (kind IN ('glasses', 'clothing', 'earrings', 'necklace')),
  anchors      jsonb       NOT NULL DEFAULT '{}',
  scale        jsonb       NOT NULL DEFAULT '{}',
