-- ===== 06_inventory.sql =====
-- 06_inventory: stock per variant, reservations, movement ledger. Only the inventory module writes here (INV-*, COR-01).
-- Reserve pattern (one statement, no read-then-write):
--   UPDATE inventory.stock_levels SET reserved = reserved + $q
--    WHERE variant_id = $v AND (unlimited OR on_hand - reserved >= $q);   -- 0 rows updated = out of stock

CREATE SCHEMA IF NOT EXISTS inventory;

CREATE TABLE inventory.stock_levels (
  variant_id uuid PRIMARY KEY,
  tenant_id  uuid        NOT NULL,
  on_hand    integer     NOT NULL DEFAULT 0,
  reserved   integer     NOT NULL DEFAULT 0,
  unlimited  boolean     NOT NULL DEFAULT false,            -- menu items, made-to-order (INV-05)
  updated_at timestamptz NOT NULL DEFAULT now(),
  CHECK (unlimited OR (on_hand >= 0 AND reserved >= 0 AND reserved <= on_hand)),
  FOREIGN KEY (tenant_id, variant_id) REFERENCES catalog.variants (tenant_id, id) ON DELETE CASCADE
);
CREATE INDEX stock_levels_tenant ON inventory.stock_levels (tenant_id);
CREATE TRIGGER stock_levels_updated BEFORE UPDATE ON inventory.stock_levels
  FOR EACH ROW EXECUTE FUNCTION platform.set_updated_at();
SELECT platform.enable_tenant_rls('inventory.stock_levels');

CREATE TABLE inventory.reservations (
  id         uuid PRIMARY KEY DEFAULT platform.uuid_v7(),
  tenant_id  uuid        NOT NULL,
  variant_id uuid        NOT NULL,
  quantity   integer     NOT NULL CHECK (quantity > 0),
  status     text        NOT NULL DEFAULT 'held' CHECK (status IN ('held', 'committed', 'released', 'expired')),
  owner_type text        NOT NULL CHECK (owner_type IN ('checkout', 'order')),
  owner_id   uuid        NOT NULL,
  expires_at timestamptz NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  FOREIGN KEY (tenant_id, variant_id) REFERENCES catalog.variants (tenant_id, id)
);
CREATE INDEX reservations_expiry ON inventory.reservations (expires_at) WHERE status = 'held';
CREATE INDEX reservations_owner ON inventory.reservations (owner_type, owner_id);
CREATE TRIGGER reservations_updated BEFORE UPDATE ON inventory.reservations
  FOR EACH ROW EXECUTE FUNCTION platform.set_updated_at();
SELECT platform.enable_tenant_rls('inventory.reservations');

-- Append-only audit of every stock change.
CREATE TABLE inventory.stock_movements (
  id         uuid PRIMARY KEY DEFAULT platform.uuid_v7(),
  tenant_id  uuid        NOT NULL,
  variant_id uuid        NOT NULL,
  delta      integer     NOT NULL CHECK (delta <> 0),
  reason     text        NOT NULL CHECK (reason IN ('restock', 'sale', 'return', 'adjustment', 'correction')),
  ref_type   text,
  ref_id     uuid,
  actor_id   uuid,
  created_at timestamptz NOT NULL DEFAULT now(),
  FOREIGN KEY (tenant_id, variant_id) REFERENCES catalog.variants (tenant_id, id)
);
CREATE INDEX stock_movements_variant ON inventory.stock_movements (variant_id, created_at DESC);
SELECT platform.enable_tenant_rls('inventory.stock_movements');

-- ===== 07_qr.sql =====
-- 07_qr: immutable codes with retargetable targets (ADR-0005, QRS-*).
-- Printed codes must outlive products: targets use ON DELETE SET NULL, never CASCADE.

CREATE SCHEMA IF NOT EXISTS qr;

CREATE TABLE qr.codes (
  id                   uuid PRIMARY KEY DEFAULT platform.uuid_v7(),
  tenant_id            uuid        NOT NULL REFERENCES identity.merchants (id),
  code                 text        NOT NULL UNIQUE CHECK (code ~ '^[A-Za-z0-9]{8,12}$'),
  target_product_id    uuid,
  target_collection_id uuid,
  target_path          text,                                 -- '{merchant-slug}/{product-slug}'; kept fresh by the qr module from catalog events
  label                text,
  status               text        NOT NULL DEFAULT 'active'
                         CHECK (status IN ('active', 'disabled', 'merchant_suspended')),
  created_by           uuid        REFERENCES identity.users (id),
  created_at           timestamptz NOT NULL DEFAULT now(),
  updated_at           timestamptz NOT NULL DEFAULT now(),
  retargeted_at        timestamptz,
  CHECK (num_nonnulls(target_product_id, target_collection_id) <= 1),   -- none = merchant home page
  FOREIGN KEY (tenant_id, target_product_id)    REFERENCES catalog.products (tenant_id, id)    ON DELETE SET NULL (target_product_id),
  FOREIGN KEY (tenant_id, target_collection_id) REFERENCES catalog.collections (tenant_id, id) ON DELETE SET NULL (target_collection_id)
);
CREATE INDEX codes_tenant ON qr.codes (tenant_id, created_at DESC);
CREATE INDEX codes_product ON qr.codes (target_product_id) WHERE target_product_id IS NOT NULL;
CREATE TRIGGER codes_updated BEFORE UPDATE ON qr.codes
  FOR EACH ROW EXECUTE FUNCTION platform.set_updated_at();

CREATE FUNCTION qr.forbid_code_change() RETURNS trigger
LANGUAGE plpgsql AS
$$ BEGIN RAISE EXCEPTION 'qr.codes.code is immutable' USING ERRCODE = 'integrity_constraint_violation'; END $$;
CREATE TRIGGER codes_code_immutable BEFORE UPDATE OF code ON qr.codes
  FOR EACH ROW WHEN (OLD.code IS DISTINCT FROM NEW.code) EXECUTE FUNCTION qr.forbid_code_change();

SELECT platform.enable_tenant_rls('qr.codes');
-- Resolve path: the scan handler does set_config('app.qr_code', '<code>', true) then SELECTs by code,
-- before any tenant is known. Public data (the same thing the redirect reveals).
CREATE POLICY lookup_by_code ON qr.codes FOR SELECT
  USING (code = nullif(current_setting('app.qr_code', true), ''));

-- Legacy ScanVista QR codes encode `{host}/p/{slug}` directly (slugs were globally unique). Printed codes cannot be
-- recalled, so `/p/{slug}` keeps redirecting to the new canonical path (QRS-06). Public data, no RLS; written by the
-- migration only. Empty unless live ScanVista data exists (05, A-04).
CREATE TABLE qr.legacy_redirects (
  legacy_slug citext      PRIMARY KEY,
  target_path text        NOT NULL,                 -- '{merchant-slug}/{product-slug}'
  created_at  timestamptz NOT NULL DEFAULT now()
);

-- ===== 08_analytics.sql =====
-- 08_analytics: raw events (time-partitioned, no foreign keys) and rollups.
-- Events outlive products on purpose: no FK, no cascade. No PII: session_hash is a salted, rotating hash (PRV-03).
-- Partitions live in schema analytics_p, which the application role cannot touch directly; it queries the parent.

CREATE SCHEMA IF NOT EXISTS analytics;
CREATE SCHEMA IF NOT EXISTS analytics_p;

CREATE TABLE analytics.events (
  event_id     uuid        NOT NULL,                     -- producer-generated; makes the COPY sink idempotent
  occurred_at  timestamptz NOT NULL,
  tenant_id    uuid        NOT NULL,
  type         text        NOT NULL CHECK (type IN
                 ('scan', 'view', 'model_interact', 'ar_launch', 'tryon_start', 'add_to_cart', 'purchase', 'similar_click')),
  qr_code_id   uuid,
  product_id   uuid,
  session_hash bytea,
  device_class text        CHECK (device_class IN ('mobile', 'tablet', 'desktop', 'unknown')),
  os           text,
  browser      text,
  country_code char(2),
  referrer     text        CHECK (referrer IN ('qr', 'search', 'similar', 'direct', 'other')),
  props        jsonb       NOT NULL DEFAULT '{}',
  PRIMARY KEY (occurred_at, event_id)
) PARTITION BY RANGE (occurred_at);

CREATE INDEX events_tenant_product_time ON analytics.events (tenant_id, product_id, occurred_at DESC);
CREATE INDEX events_tenant_type_time ON analytics.events (tenant_id, type, occurred_at DESC);

CREATE TABLE analytics_p.events_default PARTITION OF analytics.events DEFAULT;

-- Called by the scheduler ahead of time; one partition per month.
CREATE FUNCTION analytics.ensure_month_partition(month date) RETURNS text
LANGUAGE plpgsql AS
$$
DECLARE
  start_ts timestamptz := date_trunc('month', month)::timestamptz;
  end_ts   timestamptz := (date_trunc('month', month) + interval '1 month')::timestamptz;
  part     text := format('analytics_p.events_%s', to_char(month, 'YYYY_MM'));
BEGIN
  EXECUTE format('CREATE TABLE IF NOT EXISTS %s PARTITION OF analytics.events FOR VALUES FROM (%L) TO (%L)',
                 part, start_ts, end_ts);
  RETURN part;
END
$$;
SELECT analytics.ensure_month_partition(current_date);
SELECT analytics.ensure_month_partition((current_date + interval '1 month')::date);

SELECT platform.enable_tenant_rls('analytics.events');

-- Rollups (ANL-03). Dashboards read these, never the raw table.
CREATE TABLE analytics.daily_product_stats (
  tenant_id  uuid   NOT NULL,
  day        date   NOT NULL,
  product_id uuid   NOT NULL,
  type       text   NOT NULL,
  count      bigint NOT NULL DEFAULT 0 CHECK (count >= 0),
  uniques    bigint NOT NULL DEFAULT 0 CHECK (uniques >= 0),
  PRIMARY KEY (tenant_id, product_id, day, type)
);
CREATE INDEX daily_product_stats_day ON analytics.daily_product_stats (tenant_id, day);
SELECT platform.enable_tenant_rls('analytics.daily_product_stats');

-- Breakdowns by dimension; product_id null = merchant-wide.
CREATE TABLE analytics.daily_dimension_stats (
  tenant_id  uuid   NOT NULL,
  day        date   NOT NULL,
  dim        text   NOT NULL CHECK (dim IN ('device', 'os', 'browser', 'country', 'referrer')),
  key        text   NOT NULL,
  product_id uuid,
  type       text   NOT NULL,
  count      bigint NOT NULL DEFAULT 0 CHECK (count >= 0)
);
CREATE UNIQUE INDEX daily_dimension_stats_key ON analytics.daily_dimension_stats
  (tenant_id, day, dim, key, type, coalesce(product_id, '00000000-0000-0000-0000-000000000000'::uuid));
SELECT platform.enable_tenant_rls('analytics.daily_dimension_stats');

-- Holdout assignment for experiments (ANL-05, DSC-08).
CREATE TABLE analytics.experiment_assignments (
  experiment   text        NOT NULL,
  session_hash bytea       NOT NULL,
  arm          text        NOT NULL,
  assigned_at  timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (experiment, session_hash)
);

-- ===== 09_ai.sql =====
-- 09_ai: cached AI outputs and 3D generation / assisted-digitization jobs (ADR-0015). All model calls go through ai.gateway.

CREATE SCHEMA IF NOT EXISTS ai;

-- Outputs keyed by input hash so identical requests are served from cache (AIX-06, AI-02).
CREATE TABLE ai.outputs (
  id           uuid PRIMARY KEY DEFAULT platform.uuid_v7(),
  tenant_id    uuid        NOT NULL REFERENCES identity.merchants (id),
  kind         text        NOT NULL CHECK (kind IN ('page_analysis', 'comparison', 'summary', 'suggestion')),
  subject_type text        NOT NULL,
  subject_id   uuid,
  input_hash   bytea       NOT NULL,
  model        text        NOT NULL,
  output       jsonb       NOT NULL,
  created_at   timestamptz NOT NULL DEFAULT now(),
  expires_at   timestamptz
);
CREATE UNIQUE INDEX outputs_input ON ai.outputs (tenant_id, kind, input_hash);
CREATE INDEX outputs_subject ON ai.outputs (tenant_id, subject_type, subject_id);
SELECT platform.enable_tenant_rls('ai.outputs');

CREATE TABLE ai.generation_jobs (
  id               uuid PRIMARY KEY DEFAULT platform.uuid_v7(),
  tenant_id        uuid        NOT NULL,
  product_id       uuid,
  tier             text        NOT NULL CHECK (tier IN ('ai_generation', 'assisted')),
  provider         text,
  status           text        NOT NULL DEFAULT 'queued'
                     CHECK (status IN ('queued', 'running', 'qa_pending', 'approved', 'rejected', 'failed', 'refunded')),
  input_asset_ids  uuid[]      NOT NULL DEFAULT '{}',
  result_asset_id  uuid,
  qa_score         numeric(4,3) CHECK (qa_score BETWEEN 0 AND 1),
  qa_notes         jsonb       NOT NULL DEFAULT '{}',
  credits_charged  integer     NOT NULL DEFAULT 0 CHECK (credits_charged >= 0),
  error            text,
  requested_by     uuid        REFERENCES identity.users (id),
  created_at       timestamptz NOT NULL DEFAULT now(),
  updated_at       timestamptz NOT NULL DEFAULT now(),
  FOREIGN KEY (tenant_id) REFERENCES identity.merchants (id),
  FOREIGN KEY (tenant_id, product_id)      REFERENCES catalog.products (tenant_id, id) ON DELETE SET NULL (product_id),
  FOREIGN KEY (tenant_id, result_asset_id) REFERENCES assets.assets (tenant_id, id) ON DELETE SET NULL (result_asset_id)
);
CREATE INDEX generation_jobs_tenant ON ai.generation_jobs (tenant_id, created_at DESC);
CREATE INDEX generation_jobs_active ON ai.generation_jobs (status, updated_at)
  WHERE status IN ('queued', 'running', 'qa_pending');
CREATE TRIGGER generation_jobs_updated BEFORE UPDATE ON ai.generation_jobs
  FOR EACH ROW EXECUTE FUNCTION platform.set_updated_at();
SELECT platform.enable_tenant_rls('ai.generation_jobs');

-- Hosted clothing try-on (ADR-0014). Photos are deleted within 24 h; only the consent record and result key persist.
CREATE TABLE ai.tryon_requests (
  id            uuid PRIMARY KEY DEFAULT platform.uuid_v7(),
  tenant_id     uuid        NOT NULL,
  product_id    uuid        NOT NULL,
  session_hash  bytea       NOT NULL,
  provider      text        NOT NULL,
  status        text        NOT NULL DEFAULT 'queued' CHECK (status IN ('queued', 'running', 'succeeded', 'failed', 'expired')),
  consent_at    timestamptz NOT NULL,
  photo_key     text,
  result_key    text,
  credits       integer     NOT NULL DEFAULT 1 CHECK (credits >= 0),
  purge_after   timestamptz NOT NULL DEFAULT now() + interval '24 hours',
  created_at    timestamptz NOT NULL DEFAULT now(),
  FOREIGN KEY (tenant_id, product_id) REFERENCES catalog.products (tenant_id, id)
);
CREATE INDEX tryon_requests_purge ON ai.tryon_requests (purge_after) WHERE photo_key IS NOT NULL OR result_key IS NOT NULL;
SELECT platform.enable_tenant_rls('ai.tryon_requests');

-- ===== 10_discovery.sql =====
-- 10_discovery: public cross-merchant projection for similar products and global search (ADR-0016, DSC-*).
-- NOT tenant-scoped: no RLS. Only viewora_discovery_writer may write; everyone else reads. Never contains
-- tenant-private fields (cost, stock counts, drafts, unpublished items, non-opted-in merchants).
-- Partitions live in discovery_p so the application role only ever queries the parent.
-- OPEN (05 / ADR-0016): embedding dimension depends on the chosen model; 768 is a placeholder to confirm.

CREATE SCHEMA IF NOT EXISTS discovery;
CREATE SCHEMA IF NOT EXISTS discovery_p;

CREATE TABLE discovery.items (
  category_family   text        NOT NULL,
  product_id        uuid        NOT NULL,
  tenant_id         uuid        NOT NULL,                -- for same-merchant ordering and click-out only
  product_seq       bigint      NOT NULL,                -- index into the Redis in-stock bitmap
  merchant_slug     text        NOT NULL,
  product_slug      text        NOT NULL,
  title             text        NOT NULL,
  brand             text,
  category_id       integer     NOT NULL,
  colors            text[]      NOT NULL DEFAULT '{}',
  item_type         text,
  price_paise       bigint      NOT NULL CHECK (price_paise >= 0),
  thumb_key         text,
  search            tsvector,
  embedding         vector(768),
  embedding_model   text,
  near_dup_cluster  uuid,
  updated_at        timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (category_family, product_id)
) PARTITION BY LIST (category_family);

CREATE TABLE discovery_p.items_default PARTITION OF discovery.items DEFAULT;

CREATE INDEX items_tenant ON discovery.items (tenant_id);
CREATE INDEX items_product ON discovery.items (product_id);
CREATE INDEX items_search ON discovery.items USING gin (search);
CREATE INDEX items_embedding ON discovery.items USING hnsw (embedding vector_cosine_ops) WITH (m = 16, ef_construction = 64);

-- Adds a partition for a category family (called by the discovery job when a new family appears).
CREATE FUNCTION discovery.ensure_family_partition(family text) RETURNS text
LANGUAGE plpgsql AS
$$
DECLARE part text := format('discovery_p.items_%s', regexp_replace(lower(family), '[^a-z0-9]+', '_', 'g'));
BEGIN
  EXECUTE format('CREATE TABLE IF NOT EXISTS %s PARTITION OF discovery.items FOR VALUES IN (%L)', part, family);
  RETURN part;
END
$$;

-- Precomputed neighbours (offline). Availability is applied at read time from the Redis bitmap (DSC-03).
CREATE TABLE discovery.neighbors (
  category_family text        NOT NULL,
  product_id      uuid        NOT NULL,
  model_version   text        NOT NULL,
  neighbors       jsonb       NOT NULL,                  -- [{"product_id":"…","score":0.91}, …] already reranked + MMR
  computed_at     timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (category_family, product_id)
);

-- ===== 11_orders.sql =====
-- 11_orders: orders, items, status history. Carts live in State Redis until checkout (CRT-01), so no cart tables.
-- Prices are tax-inclusive (ORD-03): total = subtotal - discount + shipping; tax_paise is the tax contained in it.
-- Everything an order needs later is snapshotted: title, sku, price, address.

CREATE SCHEMA IF NOT EXISTS orders;

CREATE TABLE orders.orders (
  id                 uuid PRIMARY KEY DEFAULT platform.uuid_v7(),
  tenant_id          uuid        NOT NULL REFERENCES identity.merchants (id),
  order_number       text        NOT NULL,                       -- short, human-facing, unique per merchant
  user_id            uuid        REFERENCES identity.users (id), -- null = guest checkout
  contact_name       text        NOT NULL,
  contact_email      citext,
  contact_phone      text        NOT NULL,
  status             text        NOT NULL DEFAULT 'created'
                       CHECK (status IN ('created', 'paid', 'fulfilled', 'cancelled', 'refunded')),
  fulfillment_method text        NOT NULL CHECK (fulfillment_method IN ('shipping', 'pickup', 'dine_in')),
  shipping_address   jsonb,                                      -- snapshot; required when method = shipping
  subtotal_paise     bigint      NOT NULL CHECK (subtotal_paise >= 0),
  discount_paise     bigint      NOT NULL DEFAULT 0 CHECK (discount_paise >= 0),
  shipping_paise     bigint      NOT NULL DEFAULT 0 CHECK (shipping_paise >= 0),
  tax_paise          bigint      NOT NULL DEFAULT 0 CHECK (tax_paise >= 0),
  total_paise        bigint      NOT NULL CHECK (total_paise >= 0),
  currency           char(3)     NOT NULL DEFAULT 'INR' CHECK (currency = 'INR'),
  idempotency_key    text,
  placed_at          timestamptz NOT NULL DEFAULT now(),
  paid_at            timestamptz,
  created_at         timestamptz NOT NULL DEFAULT now(),
  updated_at         timestamptz NOT NULL DEFAULT now(),
  UNIQUE (tenant_id, id),
  UNIQUE (tenant_id, order_number),
  CHECK (total_paise = subtotal_paise - discount_paise + shipping_paise),
  CHECK (discount_paise <= subtotal_paise),
  CHECK (fulfillment_method <> 'shipping' OR shipping_address IS NOT NULL)
);
CREATE UNIQUE INDEX orders_idempotency ON orders.orders (tenant_id, idempotency_key) WHERE idempotency_key IS NOT NULL;
CREATE INDEX orders_tenant_time ON orders.orders (tenant_id, placed_at DESC);
CREATE INDEX orders_tenant_status ON orders.orders (tenant_id, status, placed_at DESC);
CREATE INDEX orders_user ON orders.orders (user_id, placed_at DESC) WHERE user_id IS NOT NULL;
CREATE TRIGGER orders_updated BEFORE UPDATE ON orders.orders
  FOR EACH ROW EXECUTE FUNCTION platform.set_updated_at();
SELECT platform.enable_tenant_rls('orders.orders');

CREATE TABLE orders.order_items (
  id               uuid PRIMARY KEY DEFAULT platform.uuid_v7(),
  tenant_id        uuid    NOT NULL,
  order_id         uuid    NOT NULL,
  product_id       uuid    NOT NULL,
  variant_id       uuid    NOT NULL,
  title            text    NOT NULL,                              -- snapshot
  sku              text,
  option_values    jsonb   NOT NULL DEFAULT '{}',
  unit_price_paise bigint  NOT NULL CHECK (unit_price_paise >= 0),
  quantity         integer NOT NULL CHECK (quantity > 0),
  line_total_paise bigint  NOT NULL CHECK (line_total_paise >= 0),
  UNIQUE (tenant_id, id),
  CHECK (line_total_paise = unit_price_paise * quantity),
  FOREIGN KEY (tenant_id, order_id)   REFERENCES orders.orders (tenant_id, id) ON DELETE CASCADE,
  FOREIGN KEY (tenant_id, product_id) REFERENCES catalog.products (tenant_id, id),
  FOREIGN KEY (tenant_id, variant_id) REFERENCES catalog.variants (tenant_id, id)
);
CREATE INDEX order_items_order ON orders.order_items (order_id);
CREATE INDEX order_items_product ON orders.order_items (tenant_id, product_id);
SELECT platform.enable_tenant_rls('orders.order_items');

CREATE TABLE orders.status_history (
  id          uuid PRIMARY KEY DEFAULT platform.uuid_v7(),
  tenant_id   uuid        NOT NULL,
  order_id    uuid        NOT NULL,
  from_status text,
  to_status   text        NOT NULL,
  actor_kind  text        NOT NULL CHECK (actor_kind IN ('shopper', 'merchant_user', 'system', 'payment_webhook')),
  actor_id    uuid,
  note        text,
  created_at  timestamptz NOT NULL DEFAULT now(),
  FOREIGN KEY (tenant_id, order_id) REFERENCES orders.orders (tenant_id, id) ON DELETE CASCADE
);
CREATE INDEX status_history_order ON orders.status_history (order_id, created_at);
SELECT platform.enable_tenant_rls('orders.status_history');

-- ===== 12_payments.sql =====
-- 12_payments: Razorpay orders/payments/refunds and the raw webhook inbox (PAY-*, COR-06).
-- Hosted checkout only: no card data is ever stored.

CREATE SCHEMA IF NOT EXISTS payments;

CREATE TABLE payments.payments (
  id                  uuid PRIMARY KEY DEFAULT platform.uuid_v7(),
  tenant_id           uuid        NOT NULL,
  order_id            uuid        NOT NULL,
  provider            text        NOT NULL DEFAULT 'razorpay' CHECK (provider = 'razorpay'),
  provider_order_id   text        NOT NULL UNIQUE,
  provider_payment_id text        UNIQUE,
  amount_paise        bigint      NOT NULL CHECK (amount_paise > 0),
  status              text        NOT NULL DEFAULT 'created'
                        CHECK (status IN ('created', 'authorized', 'captured', 'failed', 'refunded', 'partially_refunded')),
  method              text,
  failure_reason      text,
  reconciled_at       timestamptz,                                  -- set by the daily reconciliation (PAY-03)
  created_at          timestamptz NOT NULL DEFAULT now(),
  updated_at          timestamptz NOT NULL DEFAULT now(),
  UNIQUE (tenant_id, id),
  FOREIGN KEY (tenant_id, order_id) REFERENCES orders.orders (tenant_id, id)
);
CREATE INDEX payments_order ON payments.payments (order_id);
CREATE INDEX payments_unreconciled ON payments.payments (created_at) WHERE reconciled_at IS NULL AND status = 'captured';
CREATE TRIGGER payments_updated BEFORE UPDATE ON payments.payments
  FOR EACH ROW EXECUTE FUNCTION platform.set_updated_at();
SELECT platform.enable_tenant_rls('payments.payments');

CREATE TABLE payments.refunds (
  id                 uuid PRIMARY KEY DEFAULT platform.uuid_v7(),
  tenant_id          uuid        NOT NULL,
  payment_id         uuid        NOT NULL,
  order_id           uuid        NOT NULL,
  amount_paise       bigint      NOT NULL CHECK (amount_paise > 0),
  status             text        NOT NULL DEFAULT 'requested'
                       CHECK (status IN ('requested', 'processed', 'failed')),
  provider_refund_id text        UNIQUE,
  reason             text,
  requested_by       uuid        REFERENCES identity.users (id),
  idempotency_key    text,
  created_at         timestamptz NOT NULL DEFAULT now(),
  updated_at         timestamptz NOT NULL DEFAULT now(),
  FOREIGN KEY (tenant_id, payment_id) REFERENCES payments.payments (tenant_id, id),
  FOREIGN KEY (tenant_id, order_id)   REFERENCES orders.orders (tenant_id, id)
);
CREATE UNIQUE INDEX refunds_idempotency ON payments.refunds (tenant_id, idempotency_key) WHERE idempotency_key IS NOT NULL;
CREATE INDEX refunds_payment ON payments.refunds (payment_id);
CREATE TRIGGER refunds_updated BEFORE UPDATE ON payments.refunds
  FOR EACH ROW EXECUTE FUNCTION platform.set_updated_at();
SELECT platform.enable_tenant_rls('payments.refunds');

-- Raw inbox for provider webhooks. Not tenant-scoped (events arrive before the tenant is known);
-- (provider, event_id) makes replay harmless; processing tolerates reorder.
CREATE TABLE payments.webhook_events (
  provider       text        NOT NULL,
  event_id       text        NOT NULL,
  event_type     text        NOT NULL,
  payload        jsonb       NOT NULL,
  signature_ok   boolean     NOT NULL,
  received_at    timestamptz NOT NULL DEFAULT now(),
  processed_at   timestamptz,
  error          text,
  PRIMARY KEY (provider, event_id)
);
CREATE INDEX webhook_events_pending ON payments.webhook_events (received_at) WHERE processed_at IS NULL;

-- ===== 13_fulfillment.sql =====
-- 13_fulfillment: shipping/pickup tracking per order (FUL-01). The last-mile platform plugs in via the Fulfillment port later.

CREATE SCHEMA IF NOT EXISTS fulfillment;

CREATE TABLE fulfillment.fulfillments (
  id           uuid PRIMARY KEY DEFAULT platform.uuid_v7(),
  tenant_id    uuid        NOT NULL,
  order_id     uuid        NOT NULL,
  method       text        NOT NULL CHECK (method IN ('shipping', 'pickup', 'dine_in')),
  status       text        NOT NULL DEFAULT 'pending'
                 CHECK (status IN ('pending', 'packed', 'shipped', 'delivered', 'picked_up', 'failed', 'cancelled')),
  carrier      text,
  tracking_ref text,
  provider     text        NOT NULL DEFAULT 'manual',          -- 'manual' now; last-mile platform later
  provider_ref text,
  events       jsonb       NOT NULL DEFAULT '[]',
  created_at   timestamptz NOT NULL DEFAULT now(),
  updated_at   timestamptz NOT NULL DEFAULT now(),
  FOREIGN KEY (tenant_id, order_id) REFERENCES orders.orders (tenant_id, id)
);
CREATE INDEX fulfillments_order ON fulfillment.fulfillments (order_id);
CREATE INDEX fulfillments_open ON fulfillment.fulfillments (tenant_id, status)
  WHERE status IN ('pending', 'packed', 'shipped');
CREATE TRIGGER fulfillments_updated BEFORE UPDATE ON fulfillment.fulfillments
  FOR EACH ROW EXECUTE FUNCTION platform.set_updated_at();
SELECT platform.enable_tenant_rls('fulfillment.fulfillments');

-- ===== 14_reviews.sql =====
-- 14_reviews: verified-purchase reviews, moderation, aggregates, saved products (REV-*).

CREATE SCHEMA IF NOT EXISTS reviews;

CREATE TABLE reviews.reviews (
  id              uuid PRIMARY KEY DEFAULT platform.uuid_v7(),
  tenant_id       uuid        NOT NULL,
  product_id      uuid        NOT NULL,
  user_id         uuid        NOT NULL REFERENCES identity.users (id),
  order_item_id   uuid        NOT NULL,                        -- verified purchase
  rating          smallint    NOT NULL CHECK (rating BETWEEN 1 AND 5),
  title           text,
  body            text,
  media_asset_ids uuid[]      NOT NULL DEFAULT '{}',
  status          text        NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'published', 'rejected', 'hidden')),
  merchant_reply  text,
  replied_at      timestamptz,
  created_at      timestamptz NOT NULL DEFAULT now(),
  updated_at      timestamptz NOT NULL DEFAULT now(),
  UNIQUE (order_item_id),                                      -- one review per purchased item
  UNIQUE (tenant_id, id),
  FOREIGN KEY (tenant_id, product_id)    REFERENCES catalog.products (tenant_id, id) ON DELETE CASCADE,
  FOREIGN KEY (tenant_id, order_item_id) REFERENCES orders.order_items (tenant_id, id)
);
CREATE INDEX reviews_product_published ON reviews.reviews (product_id, created_at DESC) WHERE status = 'published';
CREATE INDEX reviews_moderation ON reviews.reviews (tenant_id, created_at) WHERE status = 'pending';
CREATE TRIGGER reviews_updated BEFORE UPDATE ON reviews.reviews
  FOR EACH ROW EXECUTE FUNCTION platform.set_updated_at();
SELECT platform.enable_tenant_rls('reviews.reviews');

CREATE TABLE reviews.reports (
  id         uuid PRIMARY KEY DEFAULT platform.uuid_v7(),
  tenant_id  uuid        NOT NULL,
  review_id  uuid        NOT NULL,
  reporter_id uuid       REFERENCES identity.users (id),
  reason     text        NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  FOREIGN KEY (tenant_id, review_id) REFERENCES reviews.reviews (tenant_id, id) ON DELETE CASCADE
);
SELECT platform.enable_tenant_rls('reviews.reports');

-- Maintained asynchronously by a job (REV-03); served from the product overlay cache.
CREATE TABLE reviews.product_rating_stats (
  product_id   uuid PRIMARY KEY,
  tenant_id    uuid        NOT NULL,
  review_count integer     NOT NULL DEFAULT 0 CHECK (review_count >= 0),
  rating_sum   integer     NOT NULL DEFAULT 0 CHECK (rating_sum >= 0),
  histogram    integer[]   NOT NULL DEFAULT '{0,0,0,0,0}' CHECK (cardinality(histogram) = 5),
  updated_at   timestamptz NOT NULL DEFAULT now(),
  FOREIGN KEY (tenant_id, product_id) REFERENCES catalog.products (tenant_id, id) ON DELETE CASCADE
);
SELECT platform.enable_tenant_rls('reviews.product_rating_stats');

-- Shopper wishlist. Acts across merchants, so RLS is by user, not tenant; display data for a saved list is read
-- from the public discovery projection, never from catalog.products.
CREATE TABLE reviews.saved_products (
  user_id    uuid        NOT NULL REFERENCES identity.users (id) ON DELETE CASCADE,
  product_id uuid        NOT NULL,
  tenant_id  uuid        NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (user_id, product_id),
  FOREIGN KEY (tenant_id, product_id) REFERENCES catalog.products (tenant_id, id) ON DELETE CASCADE
);
ALTER TABLE reviews.saved_products ENABLE ROW LEVEL SECURITY;
ALTER TABLE reviews.saved_products FORCE ROW LEVEL SECURITY;
CREATE POLICY own_rows ON reviews.saved_products
  USING (user_id = platform.app_user_id()) WITH CHECK (user_id = platform.app_user_id());

-- ===== 15_notifications.sql =====
-- 15_notifications: send log, opt-outs, merchant inbox (NTF-*). Recipients are stored as hashes, never in clear.

CREATE SCHEMA IF NOT EXISTS notifications;

CREATE TABLE notifications.send_log (
  id             uuid PRIMARY KEY DEFAULT platform.uuid_v7(),
  tenant_id      uuid,
  channel        text        NOT NULL CHECK (channel IN ('email', 'sms')),
  template       text        NOT NULL,
  recipient_hash bytea       NOT NULL,
  status         text        NOT NULL CHECK (status IN ('queued', 'sent', 'delivered', 'failed')),
  provider_ref   text,
  error          text,
  created_at     timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX send_log_recipient ON notifications.send_log (recipient_hash, created_at DESC);
CREATE INDEX send_log_tenant ON notifications.send_log (tenant_id, created_at DESC);
-- Rows with no tenant (OTP, platform mail) may be written but are never readable by a tenant.
ALTER TABLE notifications.send_log ENABLE ROW LEVEL SECURITY;
ALTER TABLE notifications.send_log FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON notifications.send_log
  USING (tenant_id = platform.app_tenant_id())
  WITH CHECK (tenant_id IS NULL OR tenant_id = platform.app_tenant_id());

CREATE TABLE notifications.opt_outs (
  channel        text        NOT NULL CHECK (channel IN ('email', 'sms')),
  recipient_hash bytea       NOT NULL,
  created_at     timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (channel, recipient_hash)
);

-- In-app notices for merchant staff (replaces ScanVista's notifications table).
CREATE TABLE notifications.inbox (
  id         uuid PRIMARY KEY DEFAULT platform.uuid_v7(),
  tenant_id  uuid        NOT NULL REFERENCES identity.merchants (id),
  user_id    uuid        REFERENCES identity.users (id),       -- null = all staff of the merchant
  kind       text        NOT NULL,
  title      text        NOT NULL,
  body       text,
  data       jsonb       NOT NULL DEFAULT '{}',
  read_at    timestamptz,
  created_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX inbox_unread ON notifications.inbox (tenant_id, user_id, created_at DESC) WHERE read_at IS NULL;
SELECT platform.enable_tenant_rls('notifications.inbox');

-- ===== 99_grants.sql =====
-- 99_grants: least privilege. Runs last. The application role is not the table owner and has NOBYPASSRLS,
-- so RLS (FORCE) always applies to it.

DO $$
DECLARE s text;
BEGIN
  FOREACH s IN ARRAY ARRAY['platform','identity','billing','assets','catalog','inventory','qr',
                           'analytics','ai','orders','payments','fulfillment','reviews','notifications'] LOOP
    EXECUTE format('GRANT USAGE ON SCHEMA %I TO viewora_app', s);
    EXECUTE format('GRANT SELECT, INSERT, UPDATE, DELETE ON ALL TABLES IN SCHEMA %I TO viewora_app', s);
    EXECUTE format('GRANT USAGE, SELECT ON ALL SEQUENCES IN SCHEMA %I TO viewora_app', s);
  END LOOP;
END $$;

-- Legacy QR redirects are read-only for the application.
REVOKE INSERT, UPDATE, DELETE ON qr.legacy_redirects FROM viewora_app;

-- Reference data: read-only.
GRANT USAGE ON SCHEMA ref TO viewora_app, viewora_readonly;
GRANT SELECT ON ALL TABLES IN SCHEMA ref TO viewora_app, viewora_readonly;

-- Append-only tables.
REVOKE UPDATE, DELETE, TRUNCATE ON platform.audit_log, billing.credit_ledger,
                                  inventory.stock_movements, orders.status_history FROM viewora_app;

-- Outbox relay: reads and marks published, nothing else.
GRANT USAGE ON SCHEMA platform TO viewora_relay;
GRANT SELECT, UPDATE (published_at, attempts) ON platform.outbox TO viewora_relay;

-- Discovery projection: one writer, everyone else reads. Partitions are only reachable through the parent.
GRANT USAGE ON SCHEMA discovery TO viewora_app, viewora_readonly, viewora_discovery_writer;
GRANT SELECT ON ALL TABLES IN SCHEMA discovery TO viewora_app, viewora_readonly;
GRANT SELECT, INSERT, UPDATE, DELETE ON discovery.items, discovery.neighbors TO viewora_discovery_writer;
GRANT USAGE ON SCHEMA discovery_p TO viewora_discovery_writer;

-- Read-only role for support/reporting: tenant data still goes through RLS.
GRANT USAGE ON SCHEMA catalog, analytics TO viewora_readonly;
GRANT SELECT ON ALL TABLES IN SCHEMA catalog, analytics TO viewora_readonly;